//! The query parser of the programs generated by `elanc-rs` (S6d, spec
//! D6): a port of elanc-go's package `earley` (`src/compiler-go/elanrt/
//! earley`), itself a port of the Earley parser of REM's compiled programs
//! (`src/compiler/earley`: lexer `lstream.cc` and `ichstream.cc`, parser
//! `earley.cc` and `grammar.cc`, tables `runtimeInit.cc`, semantic actions
//! `esemact`), function by function, so that the queries accepted, the
//! resolution of ambiguities (priorities, associativity) and the error
//! messages are REM's. The C names are given in the comments.
//!
//! The parser is driven by the grammar rules of the program ([`Tables`]),
//! as REM's by its `gram[]` table; the term is built from the derivation
//! by [`build`], as REM's `computeTerm` (`src/compiler/runtime/termIn.c`),
//! with a [`Builder`] given by the program. The identifiers read are
//! those of the program's table ([`crate::ident`]).
//!
//! Departures from REM, where it reads outside its arrays (elanc-go's
//! rulings): at the end of the input before a complete term, the error is
//! reported there (REM advances its completed situations past the end of
//! their rules); a string lexem prints as `STRING` or as the string in
//! double quotes (REM prints a pointer read past its table of
//! identifiers, `(null)` on macOS). No operator is AC here (S6c).

mod build;
mod lex;

use std::collections::HashMap;
use std::io::{BufRead, Write};

pub use build::{build, Builder, Tree};
pub use lex::{ident_lex, type_lex, Lexem};
use lex::*;

use crate::ident::ident_index;

/// An error that stops the program: `msg` is written on the standard
/// error and the program exits with `status` (REM's `failexit`: 1).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Fatal {
    pub msg: String,
    pub status: i32,
}

impl Fatal {
    fn new(msg: &str) -> Fatal {
        Fatal {
            msg: msg.to_string(),
            status: 1,
        }
    }
}

/// Why a query was not read.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Error {
    /// A syntax error, whose message (REM's) has been written.
    Syntax,
    /// A [`Fatal`] error (its message not written).
    Fatal(Fatal),
}

impl From<Fatal> for Error {
    fn from(f: Fatal) -> Error {
        Error::Fatal(f)
    }
}

/// A grammar rule: `sort ::= rhs`, building the symbol `symbol`; `info`
/// is the priority word (priority + associativity bits * 4096).
#[derive(Clone, Copy, Debug)]
pub struct Rule {
    pub sort: i32,
    pub symbol: i32,
    pub info: i32,
    pub rhs: &'static [RhsLexem],
}

/// A lexem of a right-hand side: its kind ([`RHS_IDENT`]: the code is the
/// index of the identifier, [`RHS_SORT`], [`RHS_CHAR`], [`RHS_NUMBER`])
/// and its code.
#[derive(Clone, Copy, Debug)]
pub struct RhsLexem(pub u8, pub i32);

/// Kinds of [`RhsLexem`] (REM's `gram[]` codes).
pub const RHS_IDENT: u8 = 0;
pub const RHS_SORT: u8 = 1;
pub const RHS_CHAR: u8 = 2;
pub const RHS_NUMBER: u8 = 3;

/// The grammar of a program and the names of its sorts.
#[derive(Clone, Copy, Debug)]
pub struct Tables {
    /// The grammar rules, in the order of REM's `gram[]` (the three
    /// grammar dumps of the `.ref` file, in file order).
    pub rules: &'static [Rule],
    /// The names of the sorts (the warnings).
    pub sort_names: &'static [(i32, &'static str)],
    /// The sorts of the standard rules (REM's `addstandards`: the
    /// positions of `intern ident`, `intern int` and `intern string` in
    /// the interpreter's table of sorts).
    pub intern_ident: i32,
    pub intern_int: i32,
    pub intern_string: i32,
}

impl Tables {
    fn sort_name(&self, s: i32) -> &str {
        self.sort_names
            .iter()
            .find(|(i, _)| *i == s)
            .map_or("", |(_, n)| n)
    }
}

// Priority word (commondefs.h).
const RNOPRIOR: i32 = 0;
const RPRIORITYMSK: i32 = 0o7777;
const RLEFTASSOC: i32 = 0o10000;
const RRIGHTASSOC: i32 = 0o20000;
const RASSOCMSK: i32 = 0o70000;
const STANDPRI: i32 = 4000;

// Semantic actions of the standard rules and of the rules building
// numbers, identifiers and strings (term/codes.h).
const NUM_TO_TERM: i32 = 67;
const IDENT_TO_TERM: i32 = 68;
const NUM_RULE: i32 = 69;
const IDENT_RULE: i32 = 70;
const STRING_TO_TERM: i32 = 81;
const STRING_RULE: i32 = 82;

/// MAXLENNTERM, the longest query (in lexems).
pub const MAX_LEXEMS: usize = 50000;

/// A rule of the parser (struct sgrammrule).
struct GRule {
    priority: i32,
    rulenumber: i32,
    leftside: Lexem,
    /// Ended by [`NO_LEXEM`].
    rside: Vec<Lexem>,
    /// In [`Tables::rules`]; `None` for a standard rule.
    index: Option<usize>,
    arity: usize,
    /// `rulenumber` is a semantic action of the parser (esemact), only for
    /// the standard rules and the `1:` rules of the `.ref` (s ::= intern
    /// int code 67, intern ident 68, intern string 81); a user operator
    /// with such a code is an operator like any other.
    action: bool,
}

/// A situation [rule, pos, i] (struct sitlist).
#[derive(Clone, Copy)]
struct Sit {
    rule: usize,
    pos: usize,
    i: usize,
}

/// The situations of a set whose next symbol is `symbol` (struct
/// psymlist), in the order they were added (REM's nextwss chain is the
/// reverse).
struct Psym {
    symbol: Lexem,
    sits: Vec<usize>,
}

/// A set of situations (struct ssits): the situations in the order they
/// were added, and by next symbol in increasing order.
struct Ssits {
    actlex: Lexem,
    sits: Vec<usize>,
    syms: Vec<Psym>,
}

impl Ssits {
    fn new() -> Ssits {
        Ssits {
            actlex: NO_LEXEM,
            sits: Vec::new(),
            syms: Vec::new(),
        }
    }

    /// FOUND: the situations whose next symbol is `sy`.
    fn found(&self, sy: Lexem) -> Option<&Psym> {
        for p in &self.syms {
            if sy <= p.symbol {
                return if p.symbol == sy { Some(p) } else { None };
            }
        }
        None
    }
}

/// REM's class grammar with the state of a parse.
struct Grammar<'r, 't> {
    rules: Vec<GRule>,
    /// The rules of each nonterminal, in order.
    nontt: HashMap<i32, Vec<usize>>,
    t: &'t Tables,
    f: Lstream<'r>,
    /// The situations of all the sets (the sets hold their indices).
    sits: Vec<Sit>,
    sitset: Vec<Ssits>,
    sitseti: usize,
    startsymbol: Lexem,
    tree: Tree,
}

impl<'r, 't> Grammar<'r, 't> {
    /// addstandards then grammarInit.
    fn new(t: &'t Tables, f: Lstream<'r>) -> Self {
        let mut g = Grammar {
            rules: Vec::new(),
            nontt: HashMap::new(),
            t,
            f,
            sits: Vec::new(),
            sitset: Vec::new(),
            sitseti: 0,
            startsymbol: NO_LEXEM,
            tree: Tree::default(),
        };
        for (sort, lexem, num) in [
            (t.intern_ident, IDENT_LEXEM, IDENT_RULE),
            (t.intern_int, JUST_NUMBER, NUM_RULE),
            (t.intern_string, STRING_LEXEM, STRING_RULE),
        ] {
            let r = g.addrul(type_lex(sort), vec![lexem], STANDPRI, num, None);
            g.rules[r].action = true;
        }
        for (i, r) in t.rules.iter().enumerate() {
            let rs: Vec<Lexem> = r
                .rhs
                .iter()
                .map(|x| match x.0 {
                    RHS_IDENT => ident_lex(x.1),
                    RHS_CHAR => char_lex(x.1),
                    RHS_SORT => type_lex(x.1),
                    _ => num_lex(x.1 as u32),
                })
                .collect();
            let gr = g.addrul(type_lex(r.sort), rs, r.info, r.symbol, Some(i));
            let intern = match r.symbol {
                NUM_TO_TERM => Some(t.intern_int),
                IDENT_TO_TERM => Some(t.intern_ident),
                STRING_TO_TERM => Some(t.intern_string),
                _ => None,
            };
            if let (Some(s), [x]) = (intern, r.rhs) {
                if x.0 == RHS_SORT && x.1 == s {
                    g.rules[gr].action = true;
                }
            }
        }
        g
    }

    /// Append a rule to the rules of its left-hand side.
    fn addrul(
        &mut self,
        leftside: Lexem,
        mut body: Vec<Lexem>,
        priority: i32,
        num: i32,
        index: Option<usize>,
    ) -> usize {
        let arity = body.iter().filter(|&&l| nonterminal(l)).count();
        body.push(NO_LEXEM);
        let r = self.rules.len();
        self.rules.push(GRule {
            priority,
            rulenumber: num,
            leftside,
            rside: body,
            index,
            arity,
            action: false,
        });
        self.nontt.entry(typeval(leftside)).or_default().push(r);
        r
    }

    /// Initialise `sitset[sitseti]`.
    fn inisitset(&mut self) {
        if self.sitseti == self.sitset.len() {
            self.sitset.push(Ssits::new());
        } else {
            self.sitset[self.sitseti] = Ssits::new();
        }
    }

    /// The situations of set `set` whose next symbol is `sy`, in the order
    /// they were added.
    fn found(&self, set: usize, sy: Lexem) -> Vec<usize> {
        self.sitset[set]
            .found(sy)
            .map_or_else(Vec::new, |p| p.sits.clone())
    }

    /// Append the situation [(rule, position), i] to `sitset[sitseti]`,
    /// unless it is there; true when added.
    fn addtosit(&mut self, rule: usize, position: usize, i: usize) -> bool {
        let sy = self.rules[rule].rside[position];
        let set = &self.sitset[self.sitseti];
        if let Some(p) = set.found(sy) {
            if p.sits.iter().any(|&s| {
                let s = &self.sits[s];
                s.rule == rule && s.pos == position && s.i == i
            }) {
                return false;
            }
        }
        let s = self.sits.len();
        self.sits.push(Sit {
            rule,
            pos: position,
            i,
        });
        let set = &mut self.sitset[self.sitseti];
        set.sits.push(s);
        // PLACE: before the first symbol not smaller than sy
        let k = set
            .syms
            .iter()
            .position(|p| sy <= p.symbol)
            .unwrap_or(set.syms.len());
        if k == set.syms.len() || set.syms[k].symbol != sy {
            set.syms.insert(
                k,
                Psym {
                    symbol: sy,
                    sits: Vec::new(),
                },
            );
        }
        set.syms[k].sits.push(s);
        true
    }

    /// Complete the current set with predictions and completions.
    fn completesit(&mut self) {
        let mut added: HashMap<i32, bool> = HashMap::new();
        let mut n = 0;
        while n < self.sitset[self.sitseti].sits.len() {
            let p = self.sits[self.sitset[self.sitseti].sits[n]];
            let l = self.rules[p.rule].rside[p.pos];
            if nonterminal(l) {
                let i = typeval(l);
                if added.insert(i, true).is_none() {
                    let rs = self.nontt.get(&i).cloned().unwrap_or_default();
                    for gr in rs {
                        self.addtosit(gr, 0, self.sitseti);
                    }
                }
            } else if is_blank(l) {
                self.addtosit(p.rule, p.pos + 1, p.i);
            } else if is_end_of_stream(l) {
                // (the nextwss chain: the last added first)
                let ps = self.found(p.i, self.rules[p.rule].leftside);
                for &s in ps.iter().rev() {
                    let p2 = self.sits[s];
                    self.addtosit(p2.rule, p2.pos + 1, p2.i);
                }
            }
            n += 1;
        }
    }

    /// SEARCHENDSIT: the situations of set `seti` at the end of their rule
    /// that satisfy `cond`, in the order they were added.
    fn searchendsit(&self, seti: usize, cond: impl Fn(&Sit) -> bool) -> Vec<usize> {
        self.found(seti, NO_LEXEM)
            .into_iter()
            .filter(|&s| cond(&self.sits[s]))
            .collect()
    }

    /// Remove from `sis` the situations that another one, from the same
    /// position, makes useless: the same operator profile (an overloaded
    /// symbol declared twice), else the one of higher priority value when
    /// both have a priority.
    fn solveconflicts(&self, mut sis: Vec<usize>) -> Vec<usize> {
        let mut i1 = 0;
        while i1 < sis.len() {
            let mut restart = false;
            let n1 = &self.rules[self.sits[sis[i1]].rule];
            let p1 = n1.priority & RPRIORITYMSK;
            let mut i2 = i1 + 1;
            while i2 < sis.len() {
                let n2 = &self.rules[self.sits[sis[i2]].rule];
                let p2 = n2.priority & RPRIORITYMSK;
                if self.sits[sis[i1]].i == self.sits[sis[i2]].i {
                    let mut ok = false;
                    if n1.rulenumber == n2.rulenumber {
                        // compare the argument sorts, then the result sort
                        ok = true;
                        let mut j = 0;
                        while ok && n1.rside[j] != NO_LEXEM && n2.rside[j] != NO_LEXEM {
                            let (l1, l2) = (n1.rside[j], n2.rside[j]);
                            if nonterminal(l1) && nonterminal(l2) {
                                ok = typeval(l1) == typeval(l2);
                            }
                            j += 1;
                        }
                        ok = ok && typeval(n1.leftside) == typeval(n2.leftside);
                    }
                    if ok {
                        sis.remove(i2);
                        continue;
                    }
                    // Marian's version
                    if p1 != RNOPRIOR && p2 != RNOPRIOR {
                        if p1 < p2 {
                            sis.remove(i2);
                            continue;
                        }
                        sis.remove(i1);
                        restart = true; // goto cont1
                        break;
                    }
                }
                i2 += 1;
            }
            if !restart {
                i1 += 1;
            }
        }
        sis
    }

    /// Solve the associativity conflicts of the situations `sis` of an
    /// argument of rule `r`: when `r` is left associative, its own
    /// situations are removed, else (right associative) only its
    /// situation starting first is kept.
    fn solveconflict2(&self, sis: Vec<usize>, r: usize) -> Vec<usize> {
        let r = &self.rules[r];
        let rp = r.priority & RASSOCMSK;
        if rp == 0 || sis.len() < 2 {
            return sis;
        }
        let mut minis: Option<usize> = None;
        for &s in &sis {
            if self.rules[self.sits[s].rule].rulenumber == r.rulenumber
                && minis.map_or(true, |m| self.sits[s].i < self.sits[m].i)
            {
                minis = Some(s);
            }
        }
        let Some(minis) = minis else { return sis };
        if rp == RLEFTASSOC {
            return sis
                .into_iter()
                .filter(|&s| self.rules[self.sits[s].rule].rulenumber != r.rulenumber)
                .collect();
        }
        vec![minis]
    }

    /// Add the situations of the previous set that read `lex`; false if
    /// none. (A rule is not read past its end: REM does it at the end of
    /// the input, see the module comment.)
    fn earleyaddnewsits(&mut self, lex: Lexem) -> bool {
        if lex == NO_LEXEM {
            return false;
        }
        let ps = self.found(self.sitseti - 1, lex);
        if ps.is_empty() {
            return false;
        }
        for &s in ps.iter().rev() {
            let s = self.sits[s];
            self.addtosit(s.rule, s.pos + 1, s.i);
        }
        true
    }

    /// qendofin: the end of a query is `end` or the end of the input.
    fn is_end(&self, l: Lexem) -> bool {
        l == ident_lex(ident_index("end").0) || is_end_of_stream(l)
    }

    /// The first pass: the sets of situations of the input up to the end
    /// of a term of sort `starts`; the start situations (solved), `None`
    /// after a syntax error (reported).
    fn earley(&mut self, starts: Lexem) -> Result<Option<Vec<usize>>, Fatal> {
        self.startsymbol = starts;
        self.sitseti = 0;
        self.inisitset();
        let rs = self.nontt.get(&typeval(starts)).cloned().unwrap_or_default();
        for r in rs {
            self.addtosit(r, 0, 0);
        }
        self.completesit();
        let mut lex = self.f.fulex();
        loop {
            loop {
                self.sitseti += 1;
                if self.sitseti >= MAX_LEXEMS {
                    return Err(Fatal::new(&format!(
                        "term is longer then MAXLENNTERM={MAX_LEXEMS} lexems\n\tsorry, FATAL !!!\n"
                    )));
                }
                self.inisitset();
                self.sitset[self.sitseti].actlex = lex;
                let mut sadded = self.earleyaddnewsits(lex);
                // identifiers, numbers and strings in general
                if is_real_id(lex) {
                    sadded = self.earleyaddnewsits(IDENT_LEXEM) || sadded;
                }
                if is_real_num(lex) {
                    sadded = self.earleyaddnewsits(JUST_NUMBER) || sadded;
                }
                if is_real_string(lex) {
                    sadded = self.earleyaddnewsits(STRING_LEXEM) || sadded;
                }
                if !sadded {
                    self.oearleyerr(self.sitseti - 1)?;
                    return Ok(None);
                }
                self.completesit();
                self.f.ilex()?;
                lex = self.f.fulex();
                if self.is_end(lex) {
                    break;
                }
            }
            // the start situations; none: continue (the end was a lexem)
            let (start, i) = (self.startsymbol, self.sitseti);
            let ends = self.searchendsit(i, |s| s.i == 0 && self.rules[s.rule].leftside == start);
            let chooselist = self.solveconflicts(ends);
            if !chooselist.is_empty() {
                return Ok(Some(chooselist));
            }
        }
    }

    /// testcond: the complete situation `fins` derives the k-th lexem `xk`
    /// of the situation `acts`.
    fn testcond(&self, fins: &Sit, acts: &Sit, k: usize, xk: Lexem) -> bool {
        if self.rules[fins.rule].leftside != xk {
            return false;
        }
        let rn = self.rules[acts.rule].rulenumber;
        self.sitset[fins.i].found(xk).map_or(false, |ps| {
            ps.sits.iter().rev().any(|&s| {
                let s = &self.sits[s];
                rn == self.rules[s.rule].rulenumber && s.pos == k && s.i == acts.i
            })
        })
    }

    /// The second pass on the situations `si` (the first one is chosen, a
    /// warning when there are others) ending at set `j`: the derivations
    /// of its arguments, right to left, then its semantic action (the
    /// derivation in reverse order).
    fn earleysecprec(&mut self, si: &[usize], j: usize) -> Result<(), Fatal> {
        if si.len() > 1 {
            self.oambigwarning(si);
        }
        let s0 = self.sits[si[0]];
        let mut k = s0.pos as isize - 1;
        let mut l = j;
        while k >= 0 {
            let xk = self.rules[s0.rule].rside[k as usize];
            if terminal(xk) {
                k -= 1;
                if !is_blank(xk) {
                    l -= 1;
                }
                continue;
            }
            let ss = self.searchendsit(l, |s| self.testcond(s, &s0, k as usize, xk));
            let ss = self.solveconflicts(ss);
            let ss = self.solveconflict2(ss, s0.rule);
            if ss.is_empty() {
                return Err(Fatal::new("[earleysecprec] int.err\n"));
            }
            self.earleysecprec(&ss, l)?;
            k -= 1;
            l = self.sits[ss[0]].i;
        }
        let lex = self.sitset[j].actlex;
        self.esemact(s0.rule, lex)
    }

    /// Write the syntax error at the lexem after set `sit`.
    fn oearleyerr(&mut self, sit: usize) -> Result<(), Fatal> {
        let mut b = String::new();
        let lex = self.f.ilex()?;
        b.push_str(&self.f.position("error"));
        b.push_str(&format!(
            "[earley] syntax error on symbol '{}'",
            self.f.erralfsy(lex)
        ));
        b.push_str("\n\tone of (");
        let mut first = true;
        for ps in &self.sitset[sit].syms {
            if terminal(ps.symbol) && !is_end_of_stream(ps.symbol) {
                b.push_str(if first { "'" } else { " '" });
                b.push_str(&self.f.erralfsy(ps.symbol));
                b.push('\'');
                first = false;
            }
        }
        b.push_str(") expected");
        b.push_str("\n\tin context ");
        for i in (sit as isize - 8).max(1) as usize..=sit {
            b.push_str(&self.f.erralfsy(self.sitset[i].actlex));
            b.push(' ');
        }
        b.push_str(&format!(" >>>{}<<< ", self.f.erralfsy(lex)));
        let mut lex = self.f.fulex();
        b.push_str(&self.f.erralfsy(lex));
        b.push(' ');
        let mut i = 0;
        while i < 8 && !self.is_end(lex) {
            self.f.ilex()?;
            lex = self.f.fulex();
            b.push_str(&self.f.erralfsy(lex));
            b.push(' ');
            i += 1;
        }
        b.push('\n');
        let _ = self.f.stderr.write_all(b.as_bytes());
        Ok(())
    }

    /// Write the ambiguity that the priorities and the associativity do
    /// not solve (the first situation is chosen).
    fn oambigwarning(&mut self, si: &[usize]) {
        let mut b = String::from("\n[warning]earley: ambiguity can't be solved in string:\n");
        for i in 1..=self.sitseti {
            b.push(' ');
            b.push_str(&self.f.alfsy(self.sitset[i].actlex));
        }
        b.push('\n');
        b.push_str("between operators :\n");
        for &s in si {
            b.push('\t');
            self.writegrrule(&mut b, self.sits[s].rule);
        }
        let _ = self.f.stderr.write_all(b.as_bytes());
    }

    /// Write a rule as `'f' '(' @ ')' \t : (s1)s;`.
    fn writegrrule(&self, b: &mut String, gr: usize) {
        let gr = &self.rules[gr];
        let body = &gr.rside[..gr.rside.len() - 1];
        for &ll in body {
            if nonterminal(ll) {
                b.push_str(" @ ");
            } else {
                b.push_str(&format!("'{}' ", self.f.alfsy(ll)));
            }
        }
        b.push_str("\t : ");
        let mut wast = false;
        for &ll in body {
            if nonterminal(ll) {
                b.push_str(if wast { " " } else { "(" });
                b.push_str(self.t.sort_name(typeval(ll)));
                wast = true;
            }
        }
        if wast {
            b.push(')');
        }
        b.push_str(self.t.sort_name(typeval(gr.leftside)));
        if gr.rulenumber >= 0 {
            match gr.priority & RASSOCMSK {
                RLEFTASSOC => b.push_str("\t assocLeft "),
                RRIGHTASSOC => b.push_str("\t assocRight "),
                _ => {}
            }
            b.push_str(&format!("\t pri {}", gr.priority & RPRIORITYMSK));
            b.push_str(&format!(" code {}", gr.rulenumber));
        } else {
            b.push_str(&format!("\t VAR({})", -gr.rulenumber));
            b.push_str(&format!("\t (pri {})", gr.priority & RPRIORITYMSK));
        }
        b.push_str(";\n");
    }
}

/// Read a term of sort `sort` up to `end` (or the end of the input) from
/// `r`, named `name` in the messages (REM: "standard input" for the query),
/// as REM's `earleyCall`: its derivation, or an error. The messages of the
/// parser (the syntax error, the ambiguity warnings) are written to
/// `stderr`.
pub fn parse(
    r: &mut dyn BufRead,
    name: &str,
    t: &Tables,
    sort: i32,
    stderr: &mut Vec<u8>,
) -> Result<Tree, Error> {
    let f = Lstream::new(Ichstream::new(r, name))?;
    let mut g = Grammar::new(t, f);
    let res = parse_with(&mut g, sort);
    stderr.extend_from_slice(&g.f.stderr);
    res
}

fn parse_with(g: &mut Grammar, sort: i32) -> Result<Tree, Error> {
    let Some(choose) = g.earley(type_lex(sort))? else {
        return Err(Error::Syntax);
    };
    let j = g.sitseti;
    g.earleysecprec(&choose, j)?;
    Ok(std::mem::take(&mut g.tree))
}

/// The lexems of `r` up to the end of the input, as the error messages
/// write them (tests of the lexer).
pub fn lexems(r: &mut dyn BufRead) -> Result<(Vec<String>, Vec<u8>), Fatal> {
    let mut f = Lstream::new(Ichstream::new(r, "standard input"))?;
    let mut out = Vec::new();
    loop {
        let l = f.ilex()?;
        if l == NO_LEXEM {
            return Ok((out, f.stderr));
        }
        out.push(f.erralfsy(l));
    }
}
